// Generates prisma/schema.postgres.prisma from prisma/schema.prisma.
//
// Local development keeps SQLite (prisma/schema.prisma). Vercel cannot use a
// SQLite file, so the production build (`npm run vercel-build`) runs this
// script, then generates the Prisma client and pushes the schema against the
// Neon Postgres database whose URL Vercel injects as DATABASE_URL.
// The generated file is git-ignored; schema.prisma stays the single source.
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("prisma/schema.prisma", "utf8");
const sqliteBlock = /datasource db \{[^}]*provider\s*=\s*"sqlite"[^}]*\}/;
if (!sqliteBlock.test(src)) {
  console.error("schema-postgres: expected a sqlite datasource block in prisma/schema.prisma");
  process.exit(1);
}

// Neon's Vercel integration provides a pooled DATABASE_URL for runtime and
// DATABASE_URL_UNPOOLED for schema changes; use the direct one when present.
const directUrl = process.env.DATABASE_URL_UNPOOLED ? '\n  directUrl = env("DATABASE_URL_UNPOOLED")' : "";
const out = src.replace(
  sqliteBlock,
  `datasource db {\n  provider = "postgresql"\n  url      = env("DATABASE_URL")${directUrl}\n}`,
);

writeFileSync(
  "prisma/schema.postgres.prisma",
  `// GENERATED by scripts/schema-postgres.mjs from schema.prisma — do not edit.\n${out}`,
);
console.log(`schema-postgres: wrote prisma/schema.postgres.prisma${directUrl ? " (with directUrl)" : ""}`);
